from PIL import Image,ImageDraw
B={3:[(820,2920,925,3160),(1180,1930,1300,2050),(1880,850,1990,990),(1035,3720,1170,3890),(1320,3170,1450,3310),(2390,2160,2500,2320)],4:[(735,3150,830,3250),(910,2710,1010,2830),(920,2480,1020,2620),(1230,1790,1350,1930),(1920,1280,2020,1390),(1910,1900,1980,1975)],5:[(990,2870,1080,2990),(1330,2130,1460,2280),(2330,1040,2440,1180),(1080,3430,1180,3540),(1530,3010,1630,3090),(2310,2480,2400,2580)],6:[(985,3260,1085,3470),(1270,2340,1390,2480),(1920,1090,2020,1220),(960,3910,1070,4050),(1280,3400,1400,3550),(1920,2630,2010,2740)],7:[(470,3010,570,3130),(740,2140,850,2250),(1170,1810,1280,1940),(1980,1550,2050,1620),(480,3610,560,3730),(740,2360,850,2460),(1140,2050,1250,2150),(1950,1730,2020,1800)]}
for j,bs in B.items():
 can=Image.new('RGB',(1500,520*((len(bs)+2)//3)),'white');d=ImageDraw.Draw(can);im=Image.open(f'packet/p{j+106:04}.png').convert('RGB')
 for i,b in enumerate(bs):
  cr=im.crop(b).resize(((b[2]-b[0])*3,(b[3]-b[1])*3));dd=ImageDraw.Draw(cr)
  for u in range((b[0]//25+1)*25,b[2],25):
   x=(u-b[0])*3;dd.line((x,0,x,cr.height),fill=(200,210,245));dd.text((x,0),str(u),fill='red')
  for v in range((b[1]//25+1)*25,b[3],25):
   y=(v-b[1])*3;dd.line((0,y,cr.width,y),fill=(200,210,245));dd.text((0,y),str(v),fill='red')
  xx=i%3*500;yy=i//3*520;can.paste(cr,(xx,yy+20));d.text((xx,yy),str(b),fill='blue')
 can.save(f'out/FB-{j}-ends.png')
